@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;500;600;700;800&family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;0,700;1,400;1,600&family=Inter:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;500;600&display=swap');

:root {
  --ink: #0d0b0a;
  --ink2: #15110f;
  --stone: #201b17;
  --stone2: #29211b;
  --gold: #c49a52;
  --gold2: #f0d59a;
  --gold-dim: #77552e;
  --crimson: #6d171b;
  --crimson2: #a52c30;
  --wine: #3a1014;
  --paper: #e8d7b4;
  --paper2: #cdb78e;
  --muted: #a99b82;
  --green: #7e9272;
  --blue: #758a9a;
  --line: rgba(201, 157, 83, 0.38);
  --shadow: 0 20px 60px rgba(0, 0, 0, 0.65);
  --serif: 'Cormorant Garamond', Georgia, serif;
  --display: 'Cinzel', Georgia, serif;
  --sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --mono: 'JetBrains Mono', monospace;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  background-color: var(--ink);
}

body {
  margin: 0;
  background: var(--ink);
  color: var(--paper);
  font-family: var(--sans);
  font-size: 14px;
  line-height: 1.6;
  background-image: 
    radial-gradient(ellipse at 50% -10%, rgba(114, 68, 28, 0.22), transparent 60%),
    linear-gradient(90deg, rgba(0, 0, 0, 0.25), transparent 25%, transparent 75%, rgba(0, 0, 0, 0.25));
  background-attachment: fixed;
  min-height: 100vh;
}

/* Typography Helpers */
.display { font-family: var(--display); }
.serif { font-family: var(--serif); }
.mono { font-family: var(--mono); }
.gold { color: var(--gold2); }
.crimson { color: var(--crimson2); }
.muted { color: var(--muted); }

.eyebrow {
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--gold);
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border: 1px solid var(--gold-dim);
  background: linear-gradient(180deg, #7c2420, #4c1113);
  color: #f6e4bd;
  padding: 11px 20px;
  border-radius: 3px;
  font-family: var(--display);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.4);
  cursor: pointer;
  transition: all 0.22s cubic-bezier(0.16, 1, 0.3, 1);
  text-decoration: none;
}

.btn:hover {
  transform: translateY(-2px);
  border-color: var(--gold);
  filter: brightness(1.15);
  box-shadow: 0 8px 24px rgba(196, 154, 82, 0.25);
  color: #ffffff;
}

.btn:active {
  transform: translateY(0);
}

.btn.secondary {
  background: rgba(21, 17, 15, 0.85);
  border-color: #8c6b39;
  color: #e8d4ad;
}

.btn.secondary:hover {
  border-color: var(--gold2);
  background: rgba(35, 27, 22, 0.95);
}

.btn.ghost {
  background: transparent;
  border-color: rgba(201, 157, 83, 0.32);
  color: var(--muted);
  box-shadow: none;
}

.btn.ghost:hover {
  color: var(--paper);
  border-color: var(--gold);
}

.btn.small {
  padding: 7px 14px;
  font-size: 10px;
}

/* Panels & Containers */
.panel {
  border: 1px solid var(--line);
  background: linear-gradient(145deg, rgba(40, 32, 25, 0.92), rgba(17, 14, 12, 0.96));
  box-shadow: var(--shadow);
  position: relative;
  border-radius: 4px;
  padding: 24px;
}

.panel::before {
  content: "";
  position: absolute;
  inset: 5px;
  border: 1px solid rgba(201, 157, 83, 0.14);
  pointer-events: none;
  border-radius: 2px;
}

.panel.paper {
  background: linear-gradient(145deg, #e6d4b1, #c8ad7e);
  color: #251a11;
  border-color: #8c6837;
}

.panel.paper::before {
  border-color: rgba(100, 70, 35, 0.25);
}

.divider {
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--gold-dim), transparent);
  margin: 24px 0;
}

/* Tag / Badge */
.tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 1px solid #8c6b39;
  padding: 4px 10px;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #e6d0a5;
  background: #211710;
  border-radius: 2px;
}

.tag.red {
  border-color: #8e3536;
  color: #f0b9ad;
  background: #3a1114;
}

.tag.green {
  border-color: #5c7656;
  color: #c3d4b8;
  background: #19251a;
}

.tag.gold {
  border-color: #c49a52;
  color: #f0d59a;
  background: #2b1f11;
}

/* Keyframe animations */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.animate-fade-in {
  animation: fadeIn 0.4s ease-out forwards;
}

@keyframes candleFlicker {
  0%, 100% { filter: drop-shadow(0 0 12px rgba(240, 213, 154, 0.45)); }
  50% { filter: drop-shadow(0 0 18px rgba(240, 213, 154, 0.7)); }
}

.candle-glow {
  animation: candleFlicker 3s infinite ease-in-out;
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

import React from "react";

export interface NavigationProps {
  currentRoute: string;
  onRouteChange: (route: string, params?: Record<string, string>) => void;
  onOpenDemoModal?: () => void;
}

