          }}
        />
        <div>
          <div
            className="display"
            style={{
              fontSize: "18px",
              fontWeight: 600,
              letterSpacing: "0.06em",
              color: "#f1dfb8",
              textShadow: "0 2px 4px rgba(0,0,0,0.8)",
