          >
            KEYS OF THE DEPARTED
          </div>
          <div
            className="serif"
            style={{
              fontSize: "12px",
              fontStyle: "italic",
              color: "#c7b591",
              marginTop: "2px",
            }}
          >
            The engineer left. Their access didn't.
          </div>
        </div>
      </div>

      {/* Main Nav Links */}
      <nav style={{ display: "flex", alignItems: "center", gap: "6px", flexWrap: "wrap" }}>
        {[
          { id: "landing", label: "Archive" },
          { id: "dashboard", label: "Investigator" },
          { id: "archive", label: "Chambers" },
          { id: "upload", label: "Intake" },
