              className="display"
              style={{
                background: "transparent",
                border: "none",
                borderBottom: isActive ? "2px solid #c49a52" : "2px solid transparent",
                color: isActive ? "#f0d59a" : "#c8b994",
                padding: "8px 12px",
                fontSize: "11px",
                fontWeight: 600,
                letterSpacing: "0.07em",
                textTransform: "uppercase",
                cursor: "pointer",
                transition: "all 0.2s ease",
              }}
            >
              {item.label}
            </button>
          );
        })}
      </nav>

      {/* Right Action buttons */}
      <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
        {onOpenDemoModal && (
          <button
            onClick={onOpenDemoModal}
            className="btn small"
            style={{
              background: "linear-gradient(180deg, #8a2024, #531114)",
              borderColor: "#c49a52",
              boxShadow: "0 0 12px rgba(109, 23, 27, 0.4)",
            }}
          >
            Guided Tour
          </button>
        )}
        <button
          onClick={() => onRouteChange("auth")}
          className="btn ghost small"
          style={{ textTransform: "uppercase" }}
        >
          Sign In
        </button>
      </div>
    </header>
  );
};

