export const ArchivePage: React.FC<{
  onRouteChange: (route: string, params?: Record<string, string>) => void;
  initialFilter?: string;
}> = ({ onRouteChange, initialFilter = "ALL" }) => {
  const [selectedChapter, setSelectedChapter] = useState<string>(initialFilter);
  const [searchQuery, setSearchQuery] = useState<string>("");
  const [selectedStatus, setSelectedStatus] = useState<string>("ALL");

  const accounts = SYNTHETIC_DEMO_DATA.accounts;

  const filteredAccounts = accounts.filter((acc) => {
    const matchesChapter = selectedChapter === "ALL" || acc.ghost_type === selectedChapter;
    const matchesStatus = selectedStatus === "ALL" || acc.owner_status === selectedStatus;
    const matchesSearch =
      searchQuery.trim().length === 0 ||
      acc.account_id.toLowerCase().includes(searchQuery.toLowerCase()) ||
      acc.tags.some((t) => t.toLowerCase().includes(searchQuery.toLowerCase())) ||
      acc.primary_quote.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesChapter && matchesStatus && matchesSearch;
  });

  return (
    <div className="animate-fade-in" style={{ maxWidth: "1340px", margin: "40px auto", padding: "0 24px" }}>
      {/* Header */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", marginBottom: "32px", borderBottom: "1px solid var(--line)", paddingBottom: "20px" }}>
        <div>
          <div className="eyebrow">DÍA DE LOS MUERTOS MACHINE VAULT</div>
          <h1 className="serif" style={{ fontSize: "38px", color: "#f0dfbd", margin: "6px 0" }}>
            The Four-Chamber Registry
          </h1>
          <p className="serif" style={{ fontSize: "16px", color: "#b9a985", margin: 0 }}>
            Browse and filter identities grouped across LOST, FORGOTTEN, LONELY, and INNOCENT classifications.
          </p>
        </div>

        <div style={{ display: "flex", gap: "10px" }}>
          <img src="/candleon.png" alt="Lit Candle" style={{ width: "24px", height: "42px", objectFit: "contain" }} />
          <div style={{ fontSize: "11px", color: "var(--muted)", maxWidth: "160px" }}>
            <strong>Lit Candle:</strong> verified supporting citation.
          </div>
        </div>
      </div>

      {/* Filter and Search Bar */}
      <div
        className="panel"
        style={{
          padding: "20px",
          marginBottom: "32px",
          display: "flex",
          gap: "18px",
          flexWrap: "wrap",
          alignItems: "center",
          justifyContent: "space-between",
        }}
      >
        {/* Search */}
        <div style={{ flex: "1 1 280px" }}>
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Filter by account id, tag, or quote..."
            style={{
              width: "100%",
              padding: "10px 14px",
              background: "rgba(13,11,10,0.85)",
              border: "1px solid var(--line)",
