          {["ALL", "LOST", "FORGOTTEN", "LONELY", "INNOCENT"].map((ch) => (
            <button
              key={ch}
              onClick={() => setSelectedChapter(ch)}
              className="btn small"
              style={{
                background: selectedChapter === ch ? "linear-gradient(180deg, #8a2024, #531114)" : "rgba(21,17,15,0.8)",
