            </button>
            <button onClick={() => onRouteChange("results")} className="btn secondary">
              View Evaluation Metrics
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from "react";

export const FreeSpiritPage: React.FC<{ onRouteChange: (route: string) => void }> = ({ onRouteChange: _onRouteChange }) => {
  const statements = [
    { id: 1, text: "I like to explore new ideas and hidden corners before I have all the answers.", trait: "curiosity" },
    { id: 2, text: "I often notice small discrepancies, timestamps, and commit signatures that others overlook.", trait: "precision" },
    { id: 3, text: "I prefer carving my own investigative path instead of relying on rigid, pre-cooked rules.", trait: "independence" },
    { id: 4, text: "I care about the human stories, intentions, and memories behind abandoned systems.", trait: "empathy" },
    { id: 5, text: "I can sit comfortably with uncertainty while waiting for verifiable evidence.", trait: "patience" },
  ];

  const [selected, setSelected] = useState<number[]>([]);
  const [revealed, setRevealed] = useState(false);

  const toggleStatement = (id: number) => {
    setSelected((prev) => (prev.includes(id) ? prev.filter((item) => item !== id) : [...prev, id]));
  };

  const getArchetype = (count: number) => {
    if (count === 0) return { title: "The Silent Watcher", desc: "You observe the vault from afar, leaving the candles untouched until the shadows speak.", asset: "/candleoff.png" };
    if (count <= 2) return { title: "The Quiet Observer", desc: "You move carefully through repository archives, respecting the quiet boundaries between past code and active systems.", asset: "/moon-waxing-crescent.png" };
    if (count === 3) return { title: "The Curious Wanderer", desc: "Driven by narrative instinct, you piece together why engineers built what they built before passing judgment.", asset: "/goldenbook.png" };
    if (count === 4) return { title: "The Keeper of Small Wonders", desc: "You see beauty and historical dignity in forgotten cron scripts, legacy bots, and silent machine access.", asset: "/rose-crimson-gold.png" };
    return { title: "The Free Spirit Archivist", desc: "Unbound by rigid dogmas, you combine deep empathy with ruthless evidence verification. You let keys rest with honor.", asset: "/heart-bleeding-gothic.png" };
  };

  const archetype = getArchetype(selected.length);

  return (
    <div className="animate-fade-in" style={{ maxWidth: "880px", margin: "40px auto", padding: "0 24px" }}>
      <div style={{ textAlign: "center", marginBottom: "36px" }}>
        <img src="/heart.png" alt="Free Spirit" style={{ width: "64px", height: "64px", objectFit: "contain", marginBottom: "12px" }} />
        <div className="eyebrow">OPTIONAL ARCHIVAL INTERLUDE</div>
        <h1 className="serif" style={{ fontSize: "38px", color: "#f0dfbd", margin: "8px 0" }}>
          Discover Your Archive Spirit
        </h1>
        <p className="serif" style={{ fontSize: "17px", color: "#b9a985", margin: 0, fontStyle: "italic" }}>
          "Every investigator brings their own philosophy to the dark repository. Choose what resonates with your nature."
        </p>
      </div>

      <div className="panel" style={{ padding: "36px", marginBottom: "32px" }}>
        <div style={{ display: "flex", flexDirection: "column", gap: "14px" }}>
          {statements.map((s) => {
            const isChecked = selected.includes(s.id);
            return (
              <div
                key={s.id}
                onClick={() => toggleStatement(s.id)}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: "16px",
                  padding: "16px 20px",
                  borderRadius: "4px",
                  border: isChecked ? "1px solid var(--gold)" : "1px solid rgba(201,157,83,0.2)",
                  background: isChecked ? "rgba(201,157,83,0.12)" : "rgba(13,11,10,0.6)",
                  cursor: "pointer",
                  transition: "all 0.2s",
                }}
              >
                <input
                  type="checkbox"
                  checked={isChecked}
                  onChange={() => {}} // Controlled by wrapper div
                  style={{ width: "18px", height: "18px", cursor: "pointer", accentColor: "var(--gold)" }}
                />
                <span className="serif" style={{ fontSize: "17px", color: isChecked ? "#ffffff" : "#d0bd98" }}>
                  {s.text}
                </span>
              </div>
            );
          })}
        </div>

        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: "28px" }}>
          <span className="mono" style={{ fontSize: "12px", color: "var(--muted)" }}>
            Selected: {selected.length} of 5 statements
          </span>
          <div style={{ display: "flex", gap: "10px" }}>
            {selected.length > 0 && (
              <button onClick={() => { setSelected([]); setRevealed(false); }} className="btn ghost small">
                Reset
              </button>
            )}
            <button onClick={() => setRevealed(true)} className="btn small">
              Reveal My Archetype ✦
            </button>
          </div>
        </div>
      </div>

      {revealed && (
        <div className="panel paper animate-fade-in" style={{ padding: "40px", textAlign: "center" }}>
          <img
            src={archetype.asset}
            alt={archetype.title}
            style={{ width: "84px", height: "84px", objectFit: "contain", margin: "0 auto 16px", filter: "drop-shadow(0 0 10px rgba(119,85,46,0.3))" }}
          />
          <div className="eyebrow" style={{ color: "#77552e" }}>YOUR INVESTIGATOR ARCHETYPE</div>
          <h2 className="display" style={{ fontSize: "26px", color: "#251a11", margin: "8px 0" }}>
            {archetype.title}
          </h2>
          <p style={{ fontSize: "15px", color: "#3a2517", maxWidth: "560px", margin: "0 auto 20px", lineHeight: "1.6" }}>
            {archetype.desc}
          </p>
          <div style={{ fontSize: "11px", color: "#68543a", fontStyle: "italic" }}>
            Note: This interlude is a local reflective experience and does not affect the security classification of machine keys.
          </div>
        </div>
      )}
    </div>
  );
};

